// Main 入口
// =====================================================================
async function main(event, context) {
    const { action } = event;
    if (!action || !exports.handlers[action]) {
        throw err('INVALID_PARAMS', '无效的操作类型');
    }
    try {
        const auth = await verifyAuth(event, context);
        if (auth.error) {
            return auth;
        }
        logger.info(`[${action}]`, { ownerId: auth.openid });
        return await exports.handlers[action](event, context, auth);
    }
    catch (error) {
        logger.error(`[${action}]`, error);
        // 透传 BusinessError 错误码
        const e = error;
        if (e && e.code && e.severity) {
            const numericCode = ERROR_CODES[e.severity] || ERROR_CODES.BUSINESS;
            return handleError(error, e.message || '操作失败', numericCode);
        }
        return handleError(error, e.message || '服务器错误', ERROR_CODES.SERVER);
    }
}
